    { uint32_t _pgx1 = cpu->gpr[29]; cpu->gpr[29] = cpu->gpr[29] + 40;
    PGXP_ALU(0x27BD0028u, cpu->gpr[29], _pgx1, 0x00000028u); }  /* 0x80030CC8: 0x27BD0028 */
